<section class="card"><h2>Employment record</h2><dl class="hr-details"><?php foreach(['job'=>'Job title','department'=>'Department','supervisor'=>'Supervisor','employment'=>'Employment type','start'=>'Start date','probation'=>'Probation review'] as $key=>$label):?><dt><?=access_h($label)?></dt><dd><?=access_h(in_array($key,['start','probation'],true)?display_date($data[$key] ?? ''):($data[$key] ?? ''))?:'—'?></dd><?php endforeach?></dl></section>
<?php if($can('hr.approve')):?><section class="card"><h2>Employment decisions</h2><div class="grid"><?php foreach(['activate'=>'Approve & activate','return_changes'=>'Return for changes','confirm_probation'=>'Confirm probation'] as $action=>$label):?><details><summary><?=access_h($label)?></summary><form method="post"><?php hr_fields($action,$id,$version);hr_reason();?><button><?=access_h($label)?></button></form></details><?php endforeach?></div></section><?php endif?>
<?php if($can('hr.manage')):?><section class="card"><h2>Account suspension & offboarding</h2><p class="muted">Historical records are retained. Linked account changes require account-management permission and password confirmation.</p><div class="grid"><?php foreach(['suspend'=>'Suspend staff & access','resume'=>'Resume staff & access'] as $action=>$label):?><details><summary><?=access_h($label)?></summary><form method="post"><?php hr_fields($action,$id,$version);hr_reason(true);?><button><?=access_h($label)?></button></form></details><?php endforeach?></div><details><summary>Start offboarding</summary><form method="post" data-hr-rich-form><?php hr_fields('offboard',$id,$version);hr_input('Effective exit date','exit_date',gmdate('Y-m-d'),'date',true);?><div class="hr-field"><label id="exit-reason-label">Offboarding reason *</label><div class="hr-editor-toolbar" role="toolbar" aria-label="Reason formatting"><?php foreach(['bold'=>'Bold','italic'=>'Italic','insertUnorderedList'=>'Bullet list','insertOrderedList'=>'Numbered list','removeFormat'=>'Clear formatting'] as $command=>$label):?><button type="button" class="secondary" data-hr-format="<?=$command?>"><?=$label?></button><?php endforeach?></div><div class="hr-rich-editor" contenteditable="true" role="textbox" aria-multiline="true" aria-required="true" aria-labelledby="exit-reason-label" data-hr-editor></div><input type="hidden" name="reason_html" data-hr-rich-value></div><?php hr_input('Confirm your current password','current_password','','password',true,'autocomplete="current-password"');?><p class="muted">Future dates schedule exit and access revocation. Unreturned items remain visible for handover.</p><button>Confirm offboarding</button></form></details></section><?php endif?>
